-- Generated by tools/generate_native_encounter_library.py from the public Bastion Library export.
return {
  ["thedeep-thought-horror-overfiend-seasonal"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "Follow the expedition compass to the broad inner hall and its three memory witnesses. The Overfiend waits there, away from its former chamber.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Hold the Overfiend at its arena origin; remain outside the three witness footprints.", "Tank Unspoken Doubts if necessary; no forced tank swap."}}, {id = "healer", label = "Healers", tips = {"Prioritize a failed Borrower and preserve raid health before a False Recollection deadline.", "Keep the reader in casting range; no unannounced charm assignment."}}, {id = "damage", label = "Damage dealers", tips = {"Assist Doubts, then return to the boss when its ward releases.", "Stop spending attacks and spells into an active memory ward; existing DoT ticks cannot skip it."}}, {id = "everyone", label = "Everyone", tips = {"Read the named memory and witness in raid text.", "Keep a reader and a backup assigned; perform only one objective at a time."}}}, phases = {{label = "Stolen Certainty", trigger = "First at 18 seconds, then 36 seconds after each completed resolution; below 15% repeat after 28 seconds.", description = "One non-tank is named as the Borrower. Broadcast the exact memory (Past, Present or Future) and its matching protected witness to the raid and the Borrower. The Borrower has 12 seconds to enter the correct fixed 20-unit witness area. Resolve using the frozen witness footprint, not a marker following the player. The current tank does not move and no second mark overlaps."}, {label = "The False Recollection", trigger = "At 70% and 35% HP, once each per pull; queue behind any active Stolen Certainty.", description = "Boss becomes fully immune to new attacks and existing DoT ticks. After 4 seconds of preparation, show a two-witness sequence at 70% or three-witness sequence at 35%. A designated reader (the raid leader initially, transferable out of combat) has 8 seconds per step to reach the named witness within 20 units and use its exact remember action. Show the complete sequence in raid text throughout; it is an observation task, not a secret riddle. The rest of the raid handles remaining Doubts. Dead or disconnected reader may be replaced immediately by a leader-assigned accepted member."}, {label = "Unbidden Thought", trigger = "First at 12 seconds, then every 24 seconds; below 15% every 24 seconds at 400 base damage rather than 300.", description = "A resistible magic pulse affects encounter participants within 150 units. It deals 300 base damage, increasing to 400 below 15% health. Pulses pause during special assignments and their recovery windows."}, {label = "Empty Mind", trigger = "Once at 15% HP.", description = "At fifteen percent, the Overfiend announces its desperation. Increase the next Stolen Certainty cadence to 28 seconds and routine pulse base to 400. Preserve 12-second warnings."}}, abilities = {{name = "Stolen Certainty", summary = "First at 18 seconds, then 36 seconds after each completed resolution; below 15% repeat after 28 seconds.", description = {"One non-tank is named as the Borrower. Broadcast the exact memory (Past, Present or Future) and its matching protected witness to the raid and the Borrower. The Borrower has 12 seconds to enter the correct fixed 20-unit witness area. Resolve using the frozen witness footprint, not a marker following the player. The current tank does not move and no second mark overlaps.", "Success: The witness reclaims the memory; no damage or add. Boss melee pauses for 3 seconds and routine pulses remain deferred through the 8-second recovery.", "Failure: The Borrower is dealt a 35%-maximum-HP hit with normal combat mitigation. Spawn one Unspoken Doubt, subject to the three-add cap. If the Borrower dies, disconnects, leaves the arena or becomes invalid, keep the original witness footprint and 12-second deadline and resolve this as a failure with its Doubt at that deadline; never retarget or silently cancel it."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "The False Recollection", summary = "At 70% and 35% HP, once each per pull; queue behind any active Stolen Certainty.", description = {"Boss becomes fully immune to new attacks and existing DoT ticks. After 4 seconds of preparation, show a two-witness sequence at 70% or three-witness sequence at 35%. A designated reader (the raid leader initially, transferable out of combat) has 8 seconds per step to reach the named witness within 20 units and use its exact remember action. Show the complete sequence in raid text throughout; it is an observation task, not a secret riddle. The rest of the raid handles remaining Doubts. Dead or disconnected reader may be replaced immediately by a leader-assigned accepted member.", "Success: Complete the two-step sequence in 20 seconds total or the three-step sequence in 28 seconds total. Ward ends immediately, the boss resumes ordinary combat, and the next special assignment waits 8 seconds.", "Failure: An incorrect exact action or the hard deadline ends the phase. Deal one 50%-maximum-HP hit to encounter participants and heal the boss by 3% of its maximum HP once. Ward always releases; this HP phase remains consumed, even if that heal crosses the threshold."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Unbidden Thought", summary = "First at 12 seconds, then every 24 seconds; below 15% every 24 seconds at 400 base damage rather than 300.", description = {"A resistible magic pulse affects encounter participants within 150 units. It deals 300 base damage, increasing to 400 below 15% health. Pulses pause during special assignments and their recovery windows.", "Success: Resistance buffs and normal mitigation reduce the routine pulse. Pulse scheduling pauses throughout special warnings, immunity phases and 8-second recovery.", "Failure: Normal combat damage only; no hidden insanity counter. An Unspoken Doubt left alive 20 seconds after spawning consumes itself for one 20%-maximum-HP hit to its current target, then depops; its deadline pauses while a special movement assignment is active."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Empty Mind", summary = "Once at 15% HP.", description = {"At fifteen percent, the Overfiend announces its desperation. Increase the next Stolen Certainty cadence to 28 seconds and routine pulse base to 400. Preserve 12-second warnings.", "Success: Maintain the same learned assignments to defeat the boss; no new final-only hidden rule.", "Failure: Same bounded failure packets as the preceding phases; no stacked surprise effect."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"An eligible seasonal group or raid leader requests this expedition from Theta Sigma in the public encounter zone. The accepted roster may contain three to seventy-two characters with current personal and server Luclin access."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the same seasonal expedition through Theta Sigma. The existing three-day instance and two-day replay deadlines continue. Saved return is available only when that expedition has been registered successfully."}}}},
  ["emeraldjungle-severilous-seasonal"] = {overview = {"Seasonal Severilous combines nearby poison bursts with random toxic gazes."}, roles = {}, phases = {}, abilities = {{name = "Toxic Secretion", summary = "A recurring gaze targets a random hated player.", description = {}, tags = {"Random target"}, roles = {}}}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Players within 70 units take the scripted poison burst every fifteen seconds.", "Be ready to heal the random player selected for Toxic Secretion every thirty-two seconds.", "At 25%, the scripted timers stop and Severilous becomes more vulnerable to archery and backstab."}}}},
  ["feerrott-swamp-terror"] = {overview = {"A druid's charmed alligator reveals the Swamp Terror."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Bring the required charmed alligator to the quest trigger with the group prepared.", "The dialogue sequence ends with the Swamp Terror appearing nearby.", "Have a tank ready to engage as soon as the creature emerges."}}}},
  ["fieldofbone-berserkers-image"] = {overview = {"Give Mardic the sealed note to enter the training area. The combat image appears 15 seconds later.", "At 75%, 50% and 25% health, the image becomes protected and stops melee for 20 seconds. Wait for each break to finish before resuming damage."}, roles = {}, phases = {{label = "Three pauses", trigger = "75%, 50% and 25% health", description = "Each threshold applies a 20-second break, then removes the protection and restores melee."}, {label = "Return from the trial", trigger = "Combat image defeated", description = "A noncombat image appears and the quest state advances. Follow the return instruction, then hail Mardic for the next step."}}, abilities = {}, sections = {}},
  ["mirb-frozen-nightmare-chromatic-bonewalkers"] = {overview = {"Turn all four chromatic bonewalkers into icy bonewalkers at the same time."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Each bonewalker cycles through gray, brown, red and icy forms as it is defeated.", "Stop attacking once a bonewalker becomes icy. Killing an icy form returns it to gray and removes it from the completion count.", "Control completed icy forms while finishing the remaining color cycles. Four simultaneous icy bonewalkers complete the event."}}}},
  ["mirb-frozen-nightmare-frostfoot-goblins"] = {overview = {"Find and defeat the Frostfoot leaders before their reinforcements overwhelm the raid."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Approaching the Frostfoot scout starts its run to the leaders’ room. The leaders appear when it reaches its destination.", "Each surviving leader creates a henchman every ten seconds. Push toward Raid Leader Sig Chol and Taskmaster Suttalp instead of staying in the scout room indefinitely.", "The event counts total spawned goblins, not only living adds. At thirty spawns, the raid is expelled and the event resets.", "Use the warning emotes to judge urgency while tanks collect the arriving henchmen."}}}},
  ["mirb-frozen-nightmare-laskuth-the-colossus"] = {overview = {"Laskuth the Colossus closes the Frozen Nightmare after its earlier challenges are resolved."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Complete the preceding tasks for Durgin Skell to bring Laskuth into the final encounter.", "Five sleet flurries also appear along the approach. Keep the route controlled before establishing the boss pull.", "Every five seconds, Laskuth has a fifty-percent chance to send his current target to the back of the room and remove that target from hate lists.", "Keep another tank ready to pick up Laskuth when the current tank is displaced. Return promptly from the back of the room while preserving the group’s healing formation."}}}},
  ["mirb-frozen-nightmare-marrow-the-broken"] = {overview = {"Marrow the Broken sheds pieces of himself that become attacking skeletons."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Beginning at 90% health and continuing at ten-percent steps through 30%, Marrow shrinks and creates a splinterbone skeleton nearby.", "Have an add tank ready before each threshold. Avoid pushing several health stages faster than the group can collect the skeletons.", "Defeating Marrow advances Durgin Skell’s bone-golem objective."}}}},
  ["mirb-frozen-nightmare-sharalla"] = {overview = {"Protect Sharalla’s remains from four starving animals."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Hailing Sharalla’s warder starts the event and summons a polar bear, two snow cougars and a leopard.", "Pull the animals away from the corpse. The corpse checks every five seconds; an animal within twenty units adds a bite toward failure.", "Animals can drop combat and run back to the corpse. Watch for returning targets and re-establish control as soon as they can be engaged.", "Ten bites fail the event. Kill all four animals before that happens to complete the defense."}}}},
  ["mirb-frozen-nightmare-sundering-sludge"] = {overview = {"The sundering sludge divides into progressively smaller enemies."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The first sludge creates four severing sludges when killed.", "Each severing sludge creates four slippery sludges. Defeat all sixteen final sludges to complete the objective.", "Control the splits in manageable groups and keep the original sludge inside its encounter room to avoid a leash and hate reset."}}}},
  ["greatdivide-high-priest-maltan-assault"] = {overview = {"At the relevant cleric pre-epic stage, give Gavon the talisman to start the assault. It summons Maltan, two priests and three priestesses together, then removes Gavon.", "The talisman is returned and the cleric quest advances. At the following stage, hailing Gavon can start the same encounter again."}, roles = {{id = "tank", label = "Tanks", tips = {"Prepare to control six enemies at the spawn point."}}}, phases = {}, abilities = {}, sections = {}},
  ["greatdivide-tenth-coldain-ring-war-narandi"] = {overview = {"Give Sentry Badain the ninth ring and declaration to begin the war briefing. Follow Aldikar's instructions and use Scout Zrelik to direct the allied forces.", "The war advances through recruit, warrior and veteran sieges. Each siege advances after four of its designated leaders are defeated, then Narandi enters the battlefield."}, roles = {{id = "tank", label = "Tanks", tips = {"Intercept advancing giants and keep pressure off Aldikar."}}, {id = "healer", label = "Healers", tips = {"Keep the allied leadership alive while the raid covers the invasion routes."}}, {id = "damage", label = "Damage dealers", tips = {"Prioritize the designated siege leaders while stopping other giants from overrunning the defenders."}}}, phases = {{label = "First siege", trigger = "After the briefing", description = "Stop recruits and defeat four captains."}, {label = "Second siege", trigger = "First siege completed", description = "Defeat warriors, their priest support and four generals."}, {label = "Third siege", trigger = "Second siege completed", description = "Defeat veterans, high priests and four warlords."}, {label = "Narandi", trigger = "Two minutes after the final siege clears", description = "Intercept Narandi before he escapes. After killing him, follow Aldikar's instruction to return the head with the ring."}}, abilities = {}, sections = {{title = "Failure and recovery", paragraphs = {"Aldikar's death before the victory stage ends the war in defeat. Narandi has both an escape route and a later timeout, so do not postpone engaging him."}, bullets = {}}}},
  ["gunthak-dimaal-the-spiritmaster-s-waves"] = {overview = {"Choose a spirit challenge with Dimaal, then survive four waves in the Cave of the Damned."}, roles = {}, phases = {}, abilities = {}, sections = {}},
  ["gunthak-lairyn-debeian-defense-krill-the-backbleeder"] = {overview = {"Escort Lairyn to his stand against the shadows, protect him through five attacks, then confront Krill the Backbleeder."}, roles = {}, phases = {}, abilities = {}, sections = {}},
  ["drachnidhivea-find-fibblebrap3-the-hive"] = {overview = {"Complete the Hive objectives to confront Foreman Zlixtil."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Progress the mission stages before expecting the foreman to become attackable.", "Regroup while his dialogue sequence plays.", "When the dialogue ends, take control of the foreman and finish the recovery objective."}}}},
  ["drachnidhivea-the-lost-gnomes"] = {overview = {"Break cocoons and lead the rescued gnomes to safety."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Clear a safe route before opening more cocoons.", "Tell a freed gnome to follow and remain close while escorting it to the rescue area.", "Use the stop dialogue when the group needs to clear ahead.", "Some rescued gnomes develop a dangerous infestation; be ready for a hostile burst along the route."}}}},
  ["drachnidhive-drithnak-the-exiled"] = {overview = {"Drithnak creates egg sacs during a fight that must stay inside its area."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Keep the boss near its encounter position to avoid the out-of-bounds response.", "Expect egg sacs on a recurring timer and have someone watch their locations.", "Control the resulting pressure while maintaining steady boss damage."}}}},
  ["drachnidhive-the-lost-notebook"] = {overview = {"Recover the lost notebook while dealing with the Hive's traps."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Follow the mission's enemy and recovery objectives through the Hive.", "When a trap engages, prepare for a group of additional drachnids.", "Move as a group and recover before triggering another trapped area."}}}},
  ["hole-master-yael"] = {overview = {"Master Yael repeatedly uses a lethal touch against the top of his hate list."}, roles = {}, phases = {}, abilities = {{name = "Cazic Touch", summary = "A recurring attack against the highest-hate target.", description = {"The first cast occurs within about two seconds of engagement, then repeats every thirty seconds while combat continues."}, tags = {"Tank"}, roles = {}}}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Expect the first touch almost immediately after engagement, followed by a thirty-second cycle.", "The touch selects the highest-hate target. If that target is a pet, the script redirects the attack to its owner.", "The script removes several Divine Aura-style protections from the selected top-hate target before casting. Plan tank recovery and replacements around the touch cycle."}}}},
  ["westkorlacha-matriarch-shyra"] = {overview = {"Fight Matriarch Shyra with her linked protectors and enforcers inside the shadow's tether."}, roles = {{id = "everyone", label = "Everyone", tips = {"Assign the full linked pack and keep every target within the shadow's tether."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Shyra, protectors and enforcers repeatedly share aggression while any is engaged.", "Every six seconds, each checks its distance from Shyra's Shadow.", "Moving farther than 210 units from that anchor heals the enemy fully, clears hate and returns it to its bind point."}}}},
  ["illsalinc-deserting-the-ranks"] = {overview = {"Enter Draygun’s sealed chamber, endure his reanimated soldiers and defeat the captain left behind."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Find the mission key and gather the group before entering the chamber. The entry sequence consumes the key and closes the door after a short warning.", "Draygun remains protected while he moves between corpses in a randomized order and raises attackers. Follow his movement and intercept each soldier.", "At the last step, he leaves a captain with additional reanimated soldiers and departs. Defeat the captain to unlock the chamber.", "Normal and hard task selections use this same event sequence but scale enemies and reward pools differently."}}}},
  ["illsalinc-emperor-draygun-the-lich-king"] = {overview = {"Draygun’s lich form feeds on lost souls and exposes a dangerous interaction with healing magic during his split phases."}, roles = {}, phases = {}, abilities = {{name = "Restored lifeforce", summary = "Specific healing spells injure the lich while the living Emperor is present.", description = {"Use only the supported spell ranks linked here. Other cast-on events in this phase restore 60,000 health to the lich."}, tags = {"Healing interaction"}, roles = {}}}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Lost souls begin arriving ninety seconds into combat, in groups of five spaced five seconds apart. Kill them before absorption: each survivor heals Draygun and increases his melee damage.", "At 85%, 60% and 40% health, the living Emperor appears for a limited window while the lich becomes immune to ordinary spells.", "During those windows, only the listed supported healing spells damage the lich through the scripted interaction. Other spells cast on him heal him instead, so stop unapproved casts.", "Keep tanks and healers assigned to the lost souls throughout the split phases. A wipe heals the lich, and an already-started add sequence can still finish spawning."}}}},
  ["overthere-glowing-cliff-golem-and-watch-sergeant-grolj"] = {overview = {"Granika reveals a glowing cliff golem guarded by undead watchmen and Watch Sergeant Grolj."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Complete Granika’s Greenmist quest hand-in only after preparing the group.", "The reveal creates the glowing golem, four undead watchmen and Grolj together at the outpost.", "Control the watchmen while the group defeats the principal targets and recovers the required quest objective."}}}},
  ["hateplaneb-innoruuk"] = {overview = {"Defeat Innoruuk’s first form, survive the Evangelist’s reinforcements, and end the god’s renewed manifestation."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The first Innoruuk’s death summons the Evangelist of Hate. After the ritual dialogue, the true Innoruuk appears.", "The Evangelist repeatedly replenishes imps, spite golems and clerics of hate. Assign add control while the main tank holds Innoruuk.", "At 30% health, the Evangelist becomes attackable and joins combat. Kill it before trying to finish Innoruuk: at 5%, Innoruuk becomes immune while the Evangelist lives.", "Remain within Innoruuk’s chamber. Pulling him too far north causes a return to his bind point.", "Five minutes without combat clears the event; the controller schedules another attempt several hours later."}}}},
  ["hateplaneb-lanys-t-vyl-teir-dal-guardian-event"] = {overview = {"A rogue’s taunts reveal Lanys T’Vyl, whose defenses alternate between physical and magical damage."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Twenty qualifying trash kills summon the Teir’Dal guardian. A rogue at the appropriate epic stage can provoke her through the dialogue.", "The final taunt, Laarthik, activates Lanys. Prepare the raid before speaking it.", "Every twenty seconds, watch the emote: when she pauses to catch her breath, magic is effective and weapon damage is heavily reduced. When she regains strength, weapon damage is effective and several spell skills are heavily reduced.", "Pulse of Pain and Avatar Power repeat on separate thirty-five-second rotations after their opening casts. Healers should expect repeated pressure while damage dealers adapt to the defensive state."}}}},
  ["hateplaneb-maestro-of-rancor"] = {overview = {"The Maestro’s performance brings supporting musicians and banshees into the hall."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"At 95% health, three silent banshees appear.", "At 75%, two accompanists grant the Maestro very high health regeneration. Kill both accompanists to remove it.", "At 40%, the silent banshees are replaced with screeching, moaning and wailing banshees. The moaning banshee repeatedly attacks the top hate target’s mana.", "Killing every active singing banshee while the Maestro lives summons two more. Manage the remaining banshees while finishing the boss.", "Stay inside the music hall. The boss leashes outside its boundaries and the event resets after sixty seconds out of combat."}}}},
  ["rathemtn-warrior-spirit-chalex-captain-krignok"] = {overview = {"Give the restored quest sword to the pile of froglok remains to summon Warrior Spirit Chalex. He moves into position and calls Krignok twenty seconds after appearing.", "Krignok attacks Chalex and summons nine undead troll marauders in three closely spaced groups. Protect the spirit while controlling the adds.", "When Chalex leaves combat, his redeemed form appears. Return the quest sword to that form within its ten-minute window."}, roles = {}, phases = {}, abilities = {}, sections = {}},
  ["takishruinsa-living-legacy-sandkeep-endurance-raid"] = {overview = {"This is a survival encounter, not a boss-kill race. Control Eothar, manage the returning adds, and keep your raid alive while the army grows stronger.", "Rewards advance once per full minute survived. A shorter attempt keeps its completed models; surviving all 70 minutes earns Model LXX and ends the battle with a raid and server-wide victory announcement.", "Everyone alive and present when the encounter begins keeps credit for the raid's progress, even after dying or leaving the zone. Arriving later does not add a player to the starting roster."}, roles = {{id = "everyone", label = "Everyone", tips = {"Be inside the instance and ready before choosing Begin. The expedition locks as combat starts, so you cannot leave for mana recovery and re-enter during the attempt.", "Keep at least half the living enemies engaged. There is no damage quota, but leaving most of the army unattended eventually ends the attempt.", "Keep more than half the starting raid alive and in the zone. Deaths and departures count toward the same failure condition."}}, {id = "tanks", label = "Tanks", tips = {"Assign a tank to Eothar. He cannot be killed, so control him rather than spending raid damage on him.", "Spread add assignments across the field and pick up replacements quickly. Defeated adds return after 12 seconds."}}, {id = "healers", label = "Healers", tips = {"Plan healing and mana use for a long fight. Melee pressure increases each minute.", "Cure curses and poisons, and watch for golem stuns and resource drains."}}, {id = "damage-control", label = "Damage and add control", tips = {"Kill the efreeti, golems, and dervishes to reduce immediate pressure, then prepare for their replacements.", "Coordinate with tanks so living enemies stay engaged. Dead enemies waiting to respawn do not count against the raid."}}}, phases = {{label = "Prepare the raid", trigger = "Before choosing Begin", description = "Enter through Dougan's Ready option, gather near Rayna or the battlefield, and assign tanks and healers. The survival clock starts only when Begin is chosen."}, {label = "Hold the line", trigger = "Begin through 69:59", description = "The expedition locks and the 27-enemy field awakens. Each full minute survived earns the next model. Adds return after death, and enemy health, melee damage, and attack strength increase over time."}, {label = "Sandkeep conquered", trigger = "70:00 survived", description = "Model LXX is earned, combat ends, and the victory is announced to the raid and server. The army withdraws after three seconds. Entry reopens for corpse recovery once the battlefield is cleared; another attempt requires a new expedition."}}, abilities = {{name = "Complex Gravity", summary = "Eothar applies a curse that slows movement and drains resources.", description = {"Keep Eothar controlled and use curse cures to relieve the debuff. He is an unkillable anchor, not the encounter's victory target."}, tags = {"Curse", "Movement", "Resource drain"}, roles = {"everyone", "tanks", "healers"}}, {name = "Curse of the Lich", summary = "The efreeti share a reduced, short-duration curse attack.", description = {"All four efreeti share a 45-60 second cooldown, including replacement spawns. Their curse expires after 18 seconds and can deal at most three damage ticks.", "The encounter reduces this spell's HP damage to one quarter of its original tuning. Its scripted ticks deal 125 base damage each before the global damage setting. Mana and endurance drains still matter, and the curse can be cured."}, tags = {"Curse", "Damage over time", "Resource drain"}, roles = {"everyone", "healers", "damage-control"}}, {name = "Whirling Smash", summary = "Golems interrupt players with a damaging stun and resource drain.", description = {"Keep healing coverage on golem tanks and be ready for disrupted casting. The encounter halves this spell's HP damage, but its other effects remain."}, tags = {"Stun", "Resource drain"}, roles = {"everyone", "tanks", "healers"}}, {name = "Dervish venom", summary = "Dervishes use poison and movement-slowing attacks.", description = {"Use poison cures and keep the dervishes controlled. Spell HP damage is halved for this encounter; movement effects can still make repositioning difficult."}, tags = {"Poison", "Movement"}, roles = {"everyone", "healers", "damage-control"}}}, sections = {{title = "Getting started", paragraphs = {"Request Sandkeep Endurance from Dougan Merule in South Ro. Requesting creates the expedition without zoning the raid in; each assigned member chooses Ready to enter The Root of Ro."}, bullets = {"Gather 6 to 54 living players near Rayna or the battlefield, then choose Begin when the raid is ready.", "All living players already in the instance are captured at the start, up to 54. Wait for everyone before beginning.", "Entry is blocked while the attempt is active, including for assigned members who die or zone out."}}, {title = "The enemy field", paragraphs = {"Eothar anchors a field of 27 enemies: one unkillable Eothar, four efreeti, eight golems, and fourteen dervishes. The 26 killable enemies return 12 seconds after death."}, bullets = {"Distribute tanking and add control instead of concentrating the entire raid on Eothar.", "Keep at least half the currently living enemies engaged with starting raid members or their pets. Other players do not satisfy this condition.", "Dead adds waiting to respawn are excluded from the idle-enemy count."}}, {title = "Failure and corpse recovery", paragraphs = {"There is no minimum DPS requirement, pressure window, or missed-DPS recovery phase. Failure is based on raid survival and leaving enemies unattended."}, bullets = {"The attempt ends if more than half the starting raid is dead or absent for five continuous seconds. Recovering to at least half alive and present resets that countdown.", "If more than half the living enemies remain unattended, the raid receives a warning at 90 seconds and fails at 120 seconds. Re-engaging enough enemies resets the warning and countdown.", "After failure, the enemies disappear after three seconds. Once cleanup finishes and entry reopens, assigned members can return through Dougan to recover corpses.", "Completed reward models are retained. Neither a failed nor a victorious instance can restart the encounter; request a new expedition for another attempt."}}, {title = "How difficulty scales", paragraphs = {"The starting raid size scales enemy health and melee damage. Larger raids must coordinate more pressure and healing rather than expecting the same enemies as a smaller force."}, bullets = {"Enemy AC rises with the captured roster, from 100 at six players to 400 at 54 players. It does not rise each minute.", "Opening enemy health is eased for the first rewards. Health, regeneration, melee damage, and attack strength grow as the run continues; enemies remain level 60.", "Endurance's authored melee damage is halved before raid-size and minute scaling. Most spell HP damage is halved, while Curse of the Lich HP damage is quartered.", "Spell HP damage currently uses the global damage setting and encounter reductions, not the raid-size or elapsed-minute melee curve."}}, {title = "Reward progress", paragraphs = {"Each full minute survived earns one model: Model I at 1:00, Model X at 10:00, and the maximum Model LXX at 70:00. Partial minutes and post-fight cleanup do not earn another model."}, bullets = {"Progress is saved for the full starting roster, including members who later die, disconnect, or leave the zone. Those losses can still trigger encounter failure.", "Your personal best never decreases. A shorter future attempt does not replace a higher result.", "Recover your earned event abacus from the reward facilitator in the Plane of Knowledge. Move it into inventory and click it to claim your best recorded model.", "Only one augment from each Living Legacy reward line may be owned. An existing augment from this line blocks another claim without consuming the abacus."}}}},
  ["scarlet-disciple-of-sun"] = {overview = {"Accept the Disciple of Sun's monk challenge and defeat him before his deadline."}, roles = {{id = "everyone", label = "Everyone", tips = {"Have the group ready before saying challenge."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"A monk on epic 1.5 steps 12 through 16 can use the challenge dialogue.", "The challenge removes his protection and immediately adds the challenger to his hate list.", "Entering combat starts a 15-minute despawn timer."}}}},
  ["scarlet-high-priest-valon-and-the-plasmatic-followers"] = {overview = {"Jimmic Adle reveals High Priest Valon with five Plasmatic followers."}, roles = {{id = "everyone", label = "Everyone", tips = {"Prepare to control several enemies immediately after the trigger."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"A cleric at the required pre-epic step starts the event through Jimmic's turn-in; the next step also supports a hail trigger.", "Valon appears with two priests and three priestesses around the same location.", "Jimmic depops after creating the encounter."}}}},
  ["eastkorlach-general-veronhar"] = {overview = {"General Veronhar orders lethal arrow volleys while his commanders assist."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"When the general orders the archers to ready their bows, duck before the five-second warning ends.", "Keep supporting commanders controlled while maintaining the boss tank.", "Fight inside the encounter area; pulling the enemies beyond its limits causes a return and cleansing response."}}}},
  ["wakening-cristoc-bonethug"] = {overview = {"Face Cristoc Bonethug and his five mercenaries during the bard prequest."}, roles = {{id = "everyone", label = "Everyone", tips = {"Prepare control for six opponents and finish the encounter before idle cleanup."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Lantaric Dar's quest interaction summons Cristoc.", "Cristoc immediately creates five Bonethug mercenaries.", "Cristoc and the mercenaries each have a thirty-minute out-of-combat despawn timer that stops while engaged."}}}},
  ["wakening-dark-disciple-master"] = {overview = {"Survive the Dark Disciple Master's escalating undead reinforcements."}, roles = {{id = "everyone", label = "Everyone", tips = {"Have add control ready before the first random threshold and save recovery for the final two waves."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"A randomly selected threshold between 60% and 70% health raises Plavo's remains.", "At 30%, three disciples rise; at 20%, another three arrive and the master casts Spiritual Echo.", "At 19%, the master casts Protection of Discord III.", "The event has a thirty-minute cleanup timer from spawn; victory creates its quest chest."}}}},
  ["wakening-wuoshi-seasonal"] = {overview = {"Respond to Wuoshi's eight-second warnings and break the grove's protective and healing bonds."}, roles = {{id = "everyone", label = "Everyone", tips = {"Follow the ground mark for spores and the moving player mark for flare.", "Switch immediately to vines, barrier guardians and the heartbloom when required."}}}, phases = {{label = "Grove mechanics", trigger = "Opening", description = "Cycle through fixed spores, a breakable vine prison and a moving flare mark."}, {label = "Flora Barrier", trigger = "75% health", description = "Kill every guardian within seventy-five seconds to avoid a heal."}, {label = "Heartbloom", trigger = "45% health", description = "Destroy the healing bloom while continuing movement responses."}, {label = "Tunare's wrath", trigger = "20% health", description = "Survive faster, stronger mechanics through the finish."}}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Toxic spores mark Wuoshi's current location: move beyond seventy feet of that fixed point before they burst.", "Destroy the strangling vine to free its marked prisoner. Solar Flare follows its marked player, who must separate at least twenty-eight feet from allies.", "At 75%, Wuoshi becomes protected and summons scaled guardians. Clear them within seventy-five seconds; failure restores eight percent of her health before the barrier falls.", "At 45%, destroy the heartbloom that restores one percent of Wuoshi's health every eight seconds.", "At 20%, warnings retain their eight-second duration but recovery gaps shorten and mechanic damage increases. A wipe clears adds and roots and restores the boss."}}}},
  ["thundercrest-a-simple-task"] = {overview = {"Transport a fragile flower and draw out the Master Courier in the garden."}, roles = {{id = "everyone", label = "Everyone", tips = {"Minimize time carrying the flower and coordinate garden kills as a group."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The flower decays while held by clients in the zone; its first decay is reached after roughly thirty seconds of accumulated time.", "The decay counter is shared and advances faster when multiple tracked flowers are present. Zoning out pauses a carried flower's contribution.", "Forty-one non-pet kills west of the garden boundary summon the Master Courier.", "Plan the planting route before picking up the flower."}}}},
  ["thundercrest-behind-closed-doors"] = {overview = {"Collect both keys and open the guarded eastern and western rooms."}, roles = {{id = "everyone", label = "Everyone", tips = {"Prepare the group before opening either room and establish control of the guards immediately."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Looting the eastern and western keys enables their respective door pairs.", "Opening a keyed room activates its general and associated guards.", "The western room contains General Tro`Lir; the eastern room contains General Veth`Lir."}}}},
  ["thundercrest-four-corners"] = {overview = {"Defeat all four linked guardians in the open-world Four Corners event."}, roles = {{id = "everyone", label = "Everyone", tips = {"Assign all four targets before pulling and avoid dropping aggression on a surviving guardian."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Engaging any named enemy places all four on the puller's hate list.", "Keep each surviving guardian engaged: ten seconds out of combat resets the group.", "Defeating all four spawns the event chest and removes the controller."}}}},
  ["thundercrest-holy-hour"] = {overview = {"Intercept the departing worshipers before too many escape Thundercrest."}, roles = {{id = "everyone", label = "Everyone", tips = {"Position along the departure route and intercept targets before they escape."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"A worshiper begins its departure route every four minutes and ten seconds.", "Unengaged departing enemies can leave by the bridge and disappear.", "The controller fails the task once the remaining enemies plus credited kills cannot satisfy the objective."}}}},
  ["thundercrest-house-of-the-autumn-rose"] = {overview = {"Survive the temple's assassin ambushes and bring down Poison Brewer Ishi."}, roles = {{id = "everyone", label = "Everyone", tips = {"Advance together and secure each ambush before moving farther."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Three hidden encounter triggers can each release a pair of assassins when engaged.", "Defeating Poison Brewer Ishi signals the bridge sequence involving Sensei Gnarlshadow.", "Clear the route carefully so multiple ambushes do not overlap."}}}},
  ["thundercrest-lair-unguarded"] = {overview = {"Recover three statues from Yar`Lir's guardians to open the northern gates."}, roles = {{id = "everyone", label = "Everyone", tips = {"Consolidate the statues on one player and react promptly to the whirlwind warning."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The Claws, Wings and Breath guardians appear at different randomly selected locations.", "The gate check runs once a minute and unlocks when one client holds all three required statues.", "When Breath of Yar`Lir warns that the whirlwind is focusing on you, crouch during the following five seconds to avoid its knockback."}}}},
  ["thundercrest-lore-warden"] = {overview = {"Challenge the Lore Warden's servants, then defeat the enraged warden."}, roles = {{id = "everyone", label = "Everyone", tips = {"Clear all three guardians and keep the fight within the hall."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The warden summons messenger drakes shortly after spawning and has a two-hour event lifetime.", "Defiant dialogue summons two Guardians of the Past and a Sentinel of Antiquity.", "Defeating all three removes the warden's protection and enlarges him for combat.", "Leaving the permitted hall area causes a return and hate reset."}}}},
  ["thundercrest-plunder-the-hoard"] = {overview = {"Plunder the hoard while handling an armed guardian and the task's final visitors."}, roles = {{id = "everyone", label = "Everyone", tips = {"Expect a pause and renewed attack when the guardian reaches half health."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"At half health, the Guardian of the Blades becomes protected, moves to its weapon display and equips a weapon before resuming combat.", "The pond interaction requires the quest gem and the proper door target.", "The search objective creates an ornate chest; looting it starts Cherie's arrival and Yar`Lir's scripted exchange."}}}},
  ["thundercrest-scions-of-thundercrest"] = {overview = {"Find the hidden tomes and use their words to challenge the three scions."}, roles = {{id = "everyone", label = "Everyone", tips = {"Loot the matching tome before speaking its phrase and prepare before each challenge."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Three sealed chests appear at distinct random locations.", "After satisfying the matching tome task objective, say 'Kor Lal Lir Toval' to the Wind, 'Vek Lal Lir Qualal' to the Storm, and 'Nil Lal Lir Keval' to the Sky.", "A valid challenge removes that scion's protection and starts combat."}}}},
  ["thundercrest-splitting-the-storm"] = {overview = {"Escort Lila Trulan to the entrance and survive the captors waiting there."}, roles = {{id = "everyone", label = "Everyone", tips = {"Use stop to park Lila safely while clearing the path, and prepare for the final two adds."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"One player claims the escort and can direct Lila with 'follow' and 'stop'.", "Other players cannot take over while that owner is still in the zone.", "Reaching the entrance area summons two captors and advances the escort objective."}}}},
  ["thundercrest-storm-chasers-raging-thunderhead"] = {overview = {"Unleash the storm event and manage the lesser thunderheads' splitting adds."}, roles = {{id = "everyone", label = "Everyone", tips = {"Expect three adds from every lesser thunderhead and control the splitting targets deliberately."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"When the three checked Storm Chaser templates are absent and the controller remains, a chaser death summons three Thunderheads and a Raging Thunderhead.", "Each lesser Thunderhead splits into three Stormfronts when killed.", "The split announces that the raging storm grows stronger."}}}},
  ["thundercrest-stormreach-challenge-goblin-dojo"] = {overview = {"Prove your group against the dojo's successive schools and its final master."}, roles = {{id = "everyone", label = "Everyone", tips = {"Stay inside the dojo and use the scripted pauses to recover before each new school."}}}, phases = {{label = "Students", trigger = "Challenge begins", description = "Defeat the elemental, emotional and animal schools in order."}, {label = "Silk and Steel", trigger = "Students defeated", description = "Control the paired masters together."}, {label = "Sensei", trigger = "After the congratulatory dialogue", description = "Remain ready for the final master rather than leaving the dojo."}}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Six players in the dojo start the challenge.", "Defeat five elemental disciples, four emotional disciples, three animal disciples, then Silk and Steel together.", "After the apparent congratulations, the Sensei becomes the final opponent.", "The dojo boundary leashes enemies back and an empty room can fail the current stage."}}}},
  ["thundercrest-the-creator"] = {overview = {"This guide covers the level 68+ mission configuration.", "Reveal the Creator through the sentries and an Identify interaction with the quest crystal."}, roles = {{id = "everyone", label = "Everyone", tips = {"Prepare the group before the Identify cast and hold the crystal on the target player's cursor."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The third actual defunct-sentry kill summons a Furious Sentry in one of two rooms.", "Cast Identify on a player holding the required energy crystal on their cursor.", "That interaction summons Creator Kro`val with one crag sentinel and three stone sentinels, and advances the Identify objective.", "The Creator reveal occurs once per controller load."}}}},
  ["thundercrest-throes-of-contagion"] = {overview = {"Prepare and plant three toxins, then escape before the poison fills Thundercrest."}, roles = {{id = "everyone", label = "Everyone", tips = {"Check the next ingredient before advancing and begin the exit run as soon as the final toxin is placed."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Each placement requires its corresponding toxin on the interacting player and consumes it.", "The first two placements create the next component corpse.", "Planting the third starts a twenty-minute evacuation timer.", "If time expires, the task ends and Poison Cloud repeatedly strikes clients and their pets."}}}},
  ["timorous-draz-nurakk-and-his-images"] = {overview = {"Prepare for Draz Nurakk's death to release a ring of hostile images."}, roles = {{id = "everyone", label = "Everyone", tips = {"Reserve healing and control for six simultaneous images."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The initial Draz Nurakk has a twenty-four-hour despawn timer.", "Killing him immediately creates six images at fixed positions: one uses a separate template from the other five.", "The death transition begins the image fight rather than ending all combat."}}}},
  ["timorous-gefaari-drokaz"] = {overview = {"Gefaari Drokaz layers chants, breaths and minions as his health falls."}, roles = {{id = "everyone", label = "Everyone", tips = {"Assign minion control and save defensive coverage for the overlapping late-stage spell cycles."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"At 90% health, repeated deathly chants begin; at 85%, the lava-breath cycle begins.", "At 60%, two minions join and a discord cloud cycle starts.", "At 30%, three more minions join with faster breath and panic pressure.", "At 25%, another three minions arrive and the boss changes melee tuning."}}}},
  ["tipt-tipt-mountain-trials-kyv-heartstriker-jhiru"] = {overview = {"Advance through cragbeasts, repeating ghosts and a riddle before facing Jhiru."}, roles = {{id = "everyone", label = "Everyone", tips = {"Clear each triggered group fully, solve the current riddle rather than guessing, and prepare a backup tank for Jhiru's hate changes."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Approaching the cragbeast trigger releases six hatchlings; killing them summons their mother.", "The ghost area releases eight spirits, each of which creates a replacement on death. Defeat the complete spirit sequence to open the key room.", "With the required key available, request Rikabi's riddle and turn in one matching answer object. Incorrect or multiple answer items have consequences.", "Keep Jhiru in his arena: leaving its boundary raises his melee damage. He lowers the hate of a top target using certain defensive disciplines.", "Jhiru's death locks the expedition and summons Master Stonespiritist Okkanu."}}}},
  ["delveb-a-goblin-s-escort"] = {overview = {"Escort the goblins in order and confront the boss at the end of the route."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Speak to Higglin and follow the mission dialogue stages in order.", "Stay close to the currently moving goblin and clear enemies along its route.", "Wait for each escort to arrive before trying the next conversation.", "The final boss becomes hostile through dialogue, so regroup before speaking."}}}},
  ["delveb-emoush-the-destroyer"] = {overview = {"Knock out all three mystics together to expose Emoush."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Coordinate the mystic kills so their unconscious periods overlap.", "Damage Emoush while all three mystics are down.", "The mystics revive after three minutes and can restore his protection while increasing his power.", "Keep healing available for recurring Rumbling Stone casts."}}}},
  ["delveb-have-note-will-travel"] = {overview = {"Draw out the Goblin Task Master, then survive his guards."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"The first thirty qualifying kills advance the alarm sequence.", "Find and defeat the Goblin Task Master when the alarm sounds.", "His death summons more guards, so keep tanks and healers ready through the aftermath."}}}},
  ["delveb-tirranun-fanning-the-flames"] = {overview = {"Tirranun survives his first defeat and returns in a stronger form."}, roles = {}, phases = {{label = "Opening fight", trigger = "Initial engagement", description = "Handle recurring tank banishment."}, {label = "Recovery", trigger = "First apparent defeat", description = "Tirranun becomes protected and regenerates while ash adds appear."}, {label = "Renewed assault", trigger = "Recovery reaches its final threshold", description = "Tirranun returns with increased health and damage, faster adds and further area attacks."}}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Keep a backup tank ready for banishment of the top-threat target in the opening fight.", "The first apparent death begins a recovery period; continue controlling the ash adds.", "As Tirranun regenerates, add spawns accelerate before he becomes attackable again.", "Spread healing coverage for his recurring area attacks and respect the unstable bridge approach."}}}},
  ["torgiran-overseer-wrank-and-the-captains"] = {overview = {"Remove Overseer Wrank's protection by defeating his four captains."}, roles = {{id = "everyone", label = "Everyone", tips = {"Complete the key turn-ins and prepare for the captain group before the overseer becomes vulnerable."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The controller begins with a protected Overseer Wrank.", "The key counter must reach exactly twenty to summon Captain Nago, Lung, Lkai and Flang.", "When all four captain-death signals arrive, the protected overseer is replaced by the combat version."}}}},
  ["torgiran-taskmaster-lugald-brokenskull"] = {overview = {"Defeat the taskmaster's supporting force to reveal his attackable form."}, roles = {{id = "everyone", label = "Everyone", tips = {"Finish the required supporting enemies and be ready to pick up the newly spawned taskmaster."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The controller counts qualifying death signals.", "The twenty-third signal removes the protected Taskmaster Luga and spawns Taskmaster Lugald Brokenskull.", "The controller then depops, making this a single transition per spawn cycle."}}}},
  ["tofs-a-body-on-loan"] = {overview = {"Sister Nhaliss now fights in one body. At 65% and 30% health she calls grave spirits to sustain her borrowed life. Kill or control them, or interrupt Soul Harvest, to deny the healing.", "The party can keep attacking Nhaliss throughout combat. There is no vessel switching, wrong-target punishment or shared-heart chase."}, roles = {{id = "everyone", label = "Everyone", tips = {"The leader chooses [begin] at the Echo Guide. Say [status] for the current combat objective.", "Pull when ready. Named abilities begin when the boss is engaged."}}, {id = "tank", label = "Tank", tips = {"Tank Nhaliss and pick up up to two grave spirits.", "The boss always accepts ordinary damage."}}, {id = "damage", label = "Damage dealers", tips = {"Kill the 2,200-HP spirits or control them to stop their healing contribution.", "Each health threshold summons a wave only once; surviving spirits cap the total at two."}}, {id = "support", label = "Healers and control", tips = {"Interrupt the six-second Soul Harvest cast if spirits remain.", "Each free spirit restores 1,000 boss health. Rooted, mezzed or stunned spirits contribute nothing."}}}, phases = {{label = "Nhaliss", trigger = "Pull when ready", description = "Fight one named. Two spirits are called at 65% and again at 30%, with a maximum of two surviving spirits. These are soft combat mechanics; they never block the boss's death."}}, abilities = {{name = "Grave Spirits", summary = "Kill or control the healing sources.", description = {"Each spirit has 2,200 HP. They use normal crowd-control rules. The two threshold waves are not repeated when healing pushes the named back above a threshold."}, tags = {"Adds", "Crowd control"}, roles = {"everyone"}}, {name = "Soul Harvest", summary = "Interrupt the cast or remove its sources.", description = {"Every 30 seconds while grave spirits remain, Nhaliss begins a six-second interruptible cast. On completion, each living uncontrolled spirit restores 1,000 health, up to the named's maximum.", "Dead or controlled spirits contribute no healing. No particular class or ritual item is required."}, tags = {"Healing", "Interruptible"}, roles = {"everyone"}}}, sections = {{title = "Expedition access and route", paragraphs = {"The Seven Silences admits groups of three to six characters of level 55 or higher; six level-60 characters are recommended. Speak to Keeper Avel Rimeglass in Iceclad. Entry requires no raid trophy.", "The eight-hour expedition and replay begin at acceptance. The lower floors start below the difficulty of the Mistmoore group expedition, then increase toward comparable pressure on the upper floors.", "Ordinary tower keys, keyring entries and the summit shortcut do not unlock this version. Each floor victory unlocks the next expedition mirror and a cleared return checkpoint. The two wings of floor six form one encounter."}, bullets = {}}, {title = "Warnings and recovery", paragraphs = {"Read the named cast warnings and say [status] for the current objective. The leader chooses [begin] at the Echo Guide, then the party pulls when ready. Boss abilities begin on engagement; a completed disengage resets the attempt.", "Defeated prerequisite warders and optional support mobs are saved before their deaths are accepted. A wipe or reload retains these kills, previously won floors, paid admission and replay deadlines. Cleared bosses cannot be repeated for another reward during this expedition.", "The group floors require no carried tools, book choices, bells, rings or valves. Ordinary tower keys and movement shortcuts still cannot bypass the event mirrors. Every group boss retains one of its four equipment rewards and its independent splinter roll.", "Root, mez and stun can help with ordinary adds. Interrupting a named is optional; when a cast is missed, the party can move or heal as described. No random loot item is required to perform a mechanic."}, bullets = {}}, {title = "Tower inhabitants", paragraphs = {"The full tower has 200 independent ambient positions across its floors and wings. Each area has between 12 and 44 inhabitants, including two native patrols, with more inhabitants in the larger rooms and corridors. Most see normal invisibility, many are genuinely undead, and nearby inhabitants can assist one another.", "Ordinary ambient kills do not complete the main named objectives, open mirrors, remove main named protections or award boss equipment or progression items.", "Ambient mobs can be rooted, mezzed, stunned or snared. Their saved 30-minute respawns wait near living players and during an engaged named fight on that floor. Native undead-targeted spells and invisibility-versus-undead detection use their actual body types.", "Ambient health ranges from 2,160 on the lowest floor to 6,240 at the summit. Native melee endpoints range from 36–96 to 66–186 before combat mitigation, about 20 percent above their previous tuning. The original spawn identities remain stable, so saved clears and respawn deadlines still apply after a reload."}, bullets = {}}}},
}
